export default async function f(
  { body, current, archive, namespace, acknowledge, resolution },
  ctx,
) {
  if (!/^[\w-]{1,80}$/.test(namespace)) throw Error("Configure unique sheet namespace");
  const key = "exchange-rates:" + namespace;
  let s = await ctx.state.get(key);
  if (s?.phase?.endsWith("-pending")) {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending " + s.phase + " for " + key);
    if (s.phase === "update-pending")
      s.phase = resolution === "confirmed" ? "archive-ready" : "update-ready";
    else s.phase = resolution === "confirmed" ? "done" : "archive-ready";
    await ctx.state.set(key, s);
  }
  if (!s || s.phase === "done") {
    if (
      body?.result !== "success" ||
      body.base_code !== "USD" ||
      !Number.isFinite(body.time_last_update_unix) ||
      typeof body.time_last_update_utc !== "string" ||
      !body.time_last_update_utc ||
      !body.conversion_rates ||
      typeof body.conversion_rates !== "object"
    )
      throw Error("Invalid ExchangeRate API response");
    if (s?.stamp === body.time_last_update_unix)
      return { phase: "done", key, range: "A1", values: [[]] };
    const rates = body.conversion_rates;
    for (const [k, v] of Object.entries(rates))
      if (!/^[A-Z]{3}$/.test(k) || typeof v !== "number" || !Number.isFinite(v) || v <= 0)
        throw Error("Invalid rate");
    s = {
      phase: "update-ready",
      stamp: body.time_last_update_unix,
      data: { ...rates, base_currency: "USD", time_last_update_utc: body.time_last_update_utc },
    };
    await ctx.state.set(key, s);
  }
  const sheet = (x) => {
    if (
      !Array.isArray(x) ||
      !x.length ||
      !Array.isArray(x[0]) ||
      x[0].some((v, i, a) => typeof v !== "string" || !v || a.indexOf(v) !== i)
    )
      throw Error("Invalid sheet headers");
    return x;
  };
  if (s.phase === "update-ready") {
    const rows = sheet(current),
      header = rows[0],
      col = header.indexOf("base_currency");
    if (col < 0 || !header.includes("time_last_update_utc"))
      throw Error("Current sheet requires base_currency and time_last_update_utc");
    const matches = rows
      .slice(1)
      .map((r, i) => (r[col] === "USD" ? i + 2 : 0))
      .filter(Boolean);
    if (matches.length !== 1) throw Error("Current sheet must contain exactly one USD row");
    const row = header.map((h, i) =>
      Object.hasOwn(s.data, h) ? s.data[h] : (rows[matches[0] - 1]?.[i] ?? ""),
    );
    s.phase = "update-pending";
    await ctx.state.set(key, s);
    return { phase: "update", key, range: "'Rates'!A" + matches[0], values: [row] };
  }
  if (s.phase === "archive-ready") {
    const rows = sheet(archive),
      header = rows[0];
    if (!header.includes("base_currency") || !header.includes("time_last_update_utc"))
      throw Error("Archive headers missing");
    const row = header.map((h) => s.data[h] ?? "");
    s.phase = "archive-pending";
    await ctx.state.set(key, s);
    return { phase: "archive", key, range: "'Archives'!A:ZZ", values: [row] };
  }
  if (s.phase === "done") return { phase: "done", key, range: "A1", values: [[]] };
  throw Error("Invalid checkpoint");
}

