export default async function f({ key, n }, ctx) {
  const s = await ctx.state.get(key);
  if (n !== 1 || s?.phase !== "update-pending") throw Error("Inspect rate update");
  s.phase = "archive-ready";
  await ctx.state.set(key, s);
  return { ok: true };
}

